"use client";

import { useState } from 'react';
import { Sidebar } from '@/components/sidebar';
import { useAppStore } from '@/lib/store';
import { Image as ImageIcon, Map } from 'lucide-react';
import Link from 'next/link';

export default function IllustrationsPage() {
  const { categories, parentCategories, illustrations } = useAppStore();
  const illustrationCategories = categories.filter(c => c.parentMenu === 'illustrations');
  const pageTitle = parentCategories['illustrations'] || '일러스트 목록';

  // 카카오페이지 보관함 스타일 탭 (ALL + 개별 카테고리)
  const [activeTab, setActiveTab] = useState<string>('all');

  const filteredIllustrations = activeTab === 'all' 
    ? illustrations 
    : illustrations.filter(i => i.category === activeTab);

  return (
    <div className="min-h-screen bg-[#fcfcfc] dark:bg-background">
      <Sidebar />
      
      <main className="min-h-screen transition-all duration-300 pt-16 lg:pt-0">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 py-12">
          {/* Header */}
          <div className="mb-8">
            <h1 className="text-2xl font-black tracking-tight text-slate-900 dark:text-white mb-2">{pageTitle}</h1>
            <p className="text-sm text-slate-500">모든 일러스트 작업물 보관함</p>
          </div>

          {/* Sub-Category Tabs */}
          <div className="flex flex-wrap items-center gap-2 mb-8 border-b border-slate-200 dark:border-slate-800 pb-4">
            <button
              onClick={() => setActiveTab('all')}
              className={`px-4 py-2 rounded-full text-sm font-bold transition-colors ${
                activeTab === 'all'
                  ? 'bg-blue-600 text-white shadow-md'
                  : 'bg-white dark:bg-muted text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-800 hover:bg-slate-50 dark:hover:bg-slate-800'
              }`}
            >
              전체
            </button>
            {illustrationCategories.map(c => (
              <button
                key={c.id}
                onClick={() => setActiveTab(c.id)}
                className={`px-4 py-2 rounded-full text-sm font-bold transition-colors ${
                  activeTab === c.id
                    ? 'bg-blue-600 text-white shadow-md'
                    : 'bg-white dark:bg-muted text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-800 hover:bg-slate-50 dark:hover:bg-slate-800'
                }`}
              >
                {c.label}
              </button>
            ))}
          </div>

          {/* Grid View */}
          {filteredIllustrations.length > 0 ? (
            <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 lg:grid-cols-6 gap-x-4 gap-y-8">
              {filteredIllustrations.slice().reverse().map(art => {
                const categoryLabel = categories.find(c => c.id === art.category)?.label || art.category;
                
                return (
                  <Link href={`/illustrations/${art.category}`} key={art.id} className="group block">
                    <div className="relative aspect-[3/4] w-full overflow-hidden rounded-md bg-slate-100 border border-slate-200/60 shadow-sm">
                      <img 
                        src={art.thumbnailUrl || art.images[0]} 
                        alt={art.title}
                        className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
                      />
                      
                      <div className="absolute top-0 right-0 p-1.5 flex flex-col gap-1 z-20">
                         <span className="bg-slate-900/70 backdrop-blur-sm text-white text-[10px] font-bold px-1.5 py-0.5 rounded shadow-sm">
                          {categoryLabel}
                        </span>
                      </div>

                      <div className="absolute inset-0 bg-black/5 opacity-0 group-hover:opacity-100 transition-opacity z-10" />
                    </div>

                    <div className="mt-2.5">
                      <h3 className="text-sm font-bold text-slate-800 line-clamp-2 leading-tight group-hover:text-blue-600 transition-colors">
                        {art.title}
                      </h3>
                      <p className="text-[11px] text-slate-500 mt-1 flex items-center gap-1 font-medium">
                        쟈몽 <span className="w-0.5 h-0.5 rounded-full bg-slate-300"></span> 일러스트
                      </p>
                    </div>
                  </Link>
                );
              })}
            </div>
          ) : (
             <div className="flex flex-col items-center justify-center py-20 bg-white dark:bg-muted rounded-2xl border border-dashed border-slate-200 dark:border-slate-800 text-slate-400">
               <ImageIcon className="h-12 w-12 mb-4 opacity-20" />
               <p className="font-medium">등록된 작품이 없습니다.</p>
             </div>
          )}
        </div>
      </main>
    </div>
  );
}
